import{_ as r,l as t,o,c as s,v as a,p as n,x as d,d as i,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"指令格式","description":"","frontmatter":{"title":"指令格式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/instruction-format.md","filePath":"cs/instruction-format.md","lastUpdated":1789023840000}'),E={name:"cs/instruction-format.md"};function h(u,e,m,A,_,f){const c=t("Mermaid");return o(),s("div",null,[e[1]||(e[1]=a('<h1 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h1><div class="epigraph"><p>取出来的 32 比特必须切成操作码与寄存器号；字段位置固定，译码才是简单的组合接线。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/harvard-von-neumann">哈佛与冯·诺依曼</a>钉死了指令作为内存中的比特。本课不重讲 PC，也不从 x86 变长指令另起。缺口是：一串 32 位还没有字段。后课译码器、寄存器堆端口、立即数符号扩展，都要知道<strong>哪几位是什么</strong>。本栏从此以 RISC-V 为运行 ISA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任意切分都能编号，但硬件希望：操作码位置固定、寄存器号对齐，以便<a href="/cs/decoder-encoder">译码器</a>与读口硬连。缺口因此不是再解释存储程序，而是 RISC-V 的几种 32 位格式：R/I/S/B/U/J。<code>opcode</code> 总在 <code>[6:0]</code>，<code>rd</code>/<code>rs1</code>/<code>rs2</code> 位置尽量固定，立即数按类型拼接并符号扩展——编码不是「人好看」，而是译码便宜。</p><p>压缩 16 位 <code>C</code> 扩展、64 位指令空间不进本课。特权指令的 <code>csr</code> 字段后置。</p><h3 id="立即数不是「指令里的无符号整数」" tabindex="-1">立即数不是「指令里的无符号整数」 <a class="header-anchor" href="#立即数不是「指令里的无符号整数」" aria-label="Permalink to &quot;立即数不是「指令里的无符号整数」&quot;">​</a></h3><p>分支与 JAL 的立即数是编码过的偏移，最低位隐含 0（半字/字对齐）。按无符号读 I 型立即数会把负数偏移变成大正数。符号扩展规则来自<a href="/cs/twos-complement">补码</a>，本课只声明哪一种格式要扩展。</p><p><span class="marginnote">Patterson/Hennessy 用一张图列六种格式。RISC-V 刻意让 <code>rs1</code>、<code>rd</code> 在 I 与 R 中同位，避免译码 MUX 数据路径。本课不把全部 opcode 表抄完，那是下一课整数指令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>R 型：<code>funct7</code>、<code>rs2</code>、<code>rs1</code>、<code>funct3</code>、<code>rd</code>、<code>opcode</code>。I 型用 12 位立即数替换 <code>funct7+rs2</code>。S/B 把立即数拆开以保持 <code>rs1</code>/<code>rs2</code> 位置。U/J 的宽立即数占满高位。译码：先看 <code>opcode</code>，再看 <code>funct3</code>/<code>funct7</code>。</p>',11)),(o(),n(p,null,{default:d(()=>[l(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WORD%5B%2232%20%E4%BD%8D%E6%8C%87%E4%BB%A4%E5%AD%97%22%5D%20--%3E%20FIELDS%5B%22opcode%20%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%E5%AD%97%E6%AE%B5%22%5D%0A%20%20FIELDS%20--%3E%20IMM%5B%22%E7%AB%8B%E5%8D%B3%E6%95%B0%E6%8B%BC%E6%8E%A5%E4%B8%8E%E7%AC%A6%E5%8F%B7%E6%89%A9%E5%B1%95%22%5D%0A%20%20IMM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%95%B4%E6%95%B0%E6%8C%87%E4%BB%A4%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定字段让单周期数据通路可以把指令位直接接到寄存器堆地址口，不必先用组合「解析器」重排（除立即数拼接）。变长 ISA 要先确定长度，取指就可能多拍。本栏不把 x86 当主干对照课。</p><p>非法编码：未定义 <code>opcode</code> 应进后课异常，而不是当 \\(X\\) 化简掉——若 CPU 必须 traps。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲微码把复杂指令拆成格式；RISC-V 整数核几乎一条指令一种组合路径。不把 ABI 寄存器别名（<code>sp</code>、<code>ra</code>）提前到调用约定课以外的语义——别名是约定，字段仍是 5 位编号。</p><p>后课默认：指令 32 位，RISC-V 六种格式；寄存器号 5 位，32 个整数寄存器。语义下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>存储程序的比特按 RISC-V 字段切开。</li><li><code>opcode</code>/<code>rd</code>/<code>rs1</code>/<code>rs2</code> 位置固定，译码是组合。</li><li>立即数按类型拼接并通常符号扩展。</li><li>出处：Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const S=r(E,[["render",h]]);export{C as __pageData,S as default};
